    result = lsf_factory_blob_lookup_locked(address, LSF_PREPAID_IP_OPTIONS, &copy);
    if (result == 1 && !lsf_prepaid_record_queue(&factory.pool, copy.context->key,
                                               copy.ticket, LSF_PREPAID_IP_OPTIONS))
        result = -1;
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

int lsf_factory_blob_finish(struct lsf_factory_blob copy, unsigned int kind)
{
    struct lsf_factory_context *context;
    unsigned long flags;
    int result = 0;
    spin_lock_irqsave(&pool_lock, flags);
    if (!lsf_factory_blob_shape(copy)) {
        lsf_factory_device_firmware_poison();
        spin_unlock_irqrestore(&pool_lock, flags);
        return 0;
    }
    if (copy.domain != LSF_FACTORY_OWNER_APPLICATION) {
        struct lsf_prepaid_key retirement_owner;
        struct lsf_prepaid_ticket retirement_pci;
        if (!lsf_factory_device_security_record_locked(copy)) {
            lsf_factory_device_firmware_poison();
            spin_unlock_irqrestore(&pool_lock, flags);
            return 0;
        }
        lsf_factory_device_firmware_snapshot_locked(&retirement_owner, &retirement_pci);
        result = lsf_factory_device_security_finish_locked(copy, kind);
        spin_unlock_irqrestore(&pool_lock, flags);
        if (result == 1)
            lsf_factory_device_firmware_schedule(retirement_owner, retirement_pci);
        return result;
    }
    context = lsf_factory_context_current(copy.context);
    if (context)
        result = lsf_prepaid_blob_finish(&factory.pool, context->key, copy.ticket, kind);
    if (!result)
        factory.pool.poisoned = 1;
    spin_unlock_irqrestore(&pool_lock, flags);
    return result;
}

