static ssize_t lsf_factory_write(struct file *file, const char __user *buffer,
                                 size_t count, loff_t *position)
{
    const struct lsf_factory_consumer *consumer = lsf_factory_selected_consumer();
    struct lsf_factory_create request;
    struct lsf_factory_context *context;
    struct lsf_scope scope;
    struct lsf_prepaid_key key;
    unsigned int i, family, type, protocol;
    unsigned long flags;
    lsf_u64 maximum, lease;
    int error;
    (void)position;
    if (count == sizeof(struct lsf_factory_bootstrap_request))
        return lsf_factory_bootstrap_write(file, buffer, count);
    if (!consumer)
        return -EOPNOTSUPP;
    if (count != sizeof(request) || copy_from_user(&request, buffer, sizeof(request)))
        return -EINVAL;
    family = le32_to_cpu(request.family);
    type = le32_to_cpu(request.type);
    protocol = le32_to_cpu(request.protocol);
    lease = le64_to_cpu(request.lease);
    if (le32_to_cpu(request.magic) != LSF_FACTORY_MAGIC ||
        le32_to_cpu(request.version) != LSF_FACTORY_VERSION || request.reserved ||
        !lease || family != AF_INET ||
        !((type == SOCK_STREAM && protocol == IPPROTO_TCP) ||
          (type == SOCK_DGRAM && protocol == IPPROTO_UDP)))
        return -EOPNOTSUPP;
    for (i = 0; i < 8; ++i)
        scope.identity[i] = le64_to_cpu(request.scope[i]);
    maximum = type == SOCK_STREAM ? LSF_TCP_BYTES : LSF_DNS_BYTES;
    mutex_lock(&factory_lock);
    if (!lsf_factory_actor(file)) {
        error = -EPERM;
        goto out;
    }
    if (!factory.device || factory.device->bootstrap_state != LSF_FACTORY_BOOTSTRAP_READY) {
        error = -EAGAIN;
        goto out;
    }
    error = lsf_factory_device_firmware_retirement_error();
    if (error)
        goto out;
    if (READ_ONCE(factory.uncertain) || factory.reply_pending ||
        factory.inflight || lease <= factory.last_lease) {
        error = -EPERM;
        goto out;
    }
    /* Context exists before the consumer may enter ANY outer allocation/LSM.
     * No sock_create_kern fallback, socket lookup or later attestation exists. */
    spin_lock_irqsave(&pool_lock, flags);
    error = lsf_prepaid_context_create(&factory.pool, scope, maximum, &key);
    spin_unlock_irqrestore(&pool_lock, flags);
    if (!error) {
        error = -ENOBUFS;
        goto out;
    }
    context = &factory.contexts[key.slot];
    context->key = key;
    context->net = factory.net;
    context->lease = lease;
    factory.last_lease = lease;
    factory.inflight = 1;
    /* A native caller must retain this original lease after possible entry,
     * even when copy-out fails, the fd closes, or create reports uncertainty. */
    mutex_unlock(&factory_lock);
    error = consumer->create(factory.net, family, type, protocol, context, &context->socket);
    mutex_lock(&factory_lock);
    factory.inflight = 0;
    if (error || !context->socket || factory.pool.stopped) {
        WRITE_ONCE(factory.uncertain, 1);
        error = error < 0 ? error : -EIO;
        goto out;
    }
    factory.reply.lease = cpu_to_le64(lease);
    factory.reply.handle = cpu_to_le64(key.generation);
    factory.reply_pending = 1;
    error = sizeof(request);
out:
    mutex_unlock(&factory_lock);
    return error;
}

static ssize_t lsf_factory_read(struct file *file, char __user *buffer,
                                size_t count, loff_t *position)
{
    int error = -EINVAL;
    (void)position;
    if (count == sizeof(struct lsf_factory_bootstrap_status))
        return lsf_factory_bootstrap_read(file, buffer, count);
    if (count == sizeof(struct lsf_factory_bootstrap_diagnostic))
        return lsf_factory_bootstrap_diagnostic_read(file, buffer, count);
    mutex_lock(&factory_lock);
    if (!lsf_factory_actor(file))
        error = -EPERM;
    else if (!factory.device || factory.device->bootstrap_state != LSF_FACTORY_BOOTSTRAP_READY)
        error = -EAGAIN;
    else if (lsf_factory_device_firmware_retirement_error())
        error = lsf_factory_device_firmware_retirement_error();
    else if (count == sizeof(factory.reply) && factory.reply_pending) {
        if (copy_to_user(buffer, &factory.reply, sizeof(factory.reply))) {
            WRITE_ONCE(factory.uncertain, 1);
            error = -EFAULT;
        } else {
            factory.reply_pending = 0;
            error = sizeof(factory.reply);
        }
    }
    mutex_unlock(&factory_lock);
    return error;
}

static int lsf_factory_release(struct inode *inode, struct file *file)
{
    unsigned int i;
    struct lsf_cleanup_root_release release = {0};
    int transferred;
    (void)inode;
    (void)file;
    mutex_lock(&factory_lock);
    if (file->private_data == &factory && factory.device)
        factory.device->bootstrap_state = LSF_FACTORY_BOOTSTRAP_CLOSED;
    lsf_cleanup_admission_close();
    mutex_unlock(&factory_lock);
    lsf_prepaid_cleanup_worker_destroy_full();
    mutex_lock(&factory_lock);
    /* A finite scan detaches only this original context's published cache
     * births under the original cache lock. Real callbacks still own them.
     * Genuine late descendants may be born after this scan; they stay charged
     * and cannot make this an acknowledgement of complete retirement. */
    for (i = 0; i < LSF_FACTORY_CONTEXTS; ++i) {
        lsf_prepaid_netport_drain(&factory.contexts[i]);
        lsf_prepaid_sidcache_drain(&factory.contexts[i]);
    }
#ifdef LSF_STREAM_AVC_SOURCE
    for (i = 0; i < LSF_FACTORY_CONTEXTS; ++i)
        lsf_prepaid_avc_drain(&factory.contexts[i]);
#endif
#ifdef LSF_STREAM_ROUTE_CACHE_SOURCE
    for (i = 0; i < LSF_FACTORY_CONTEXTS; ++i)
        lsf_prepaid_route_cache_drain(&factory.contexts[i]);
#endif
    lsf_prepaid_device_sidcache_drain();
    lsf_prepaid_cleanup_sidcache_drain();
#ifdef LSF_STREAM_AVC_SOURCE
    lsf_prepaid_device_avc_drain();
    lsf_prepaid_cleanup_avc_drain();
#endif
    /* Device cache scans, like application scans, leave actual RCU
     * callbacks and any legitimate late descendants charged. No single
     * pass is complete retirement or an acknowledgement of backing. */
    /* Actual final VFS custody transfers AFTER the last FD cache/Root
     * use. This never authorizes a physical return by itself. */
    transferred = lsf_cleanup_root_fd_handoff_locked(file);
    if (transferred == 1)
        (void)lsf_cleanup_root_release_take_locked(&release);
    mutex_unlock(&factory_lock);
    lsf_cleanup_root_release_physical(release);
    if (transferred)
        wake_up_process(kthreadd_task);
    return 0;
}

static const struct file_operations lsf_factory_operations = {
    .owner = THIS_MODULE,
    .open = lsf_factory_open,
    .read = lsf_factory_read,
    .write = lsf_factory_write,
    .release = lsf_factory_release,
    .llseek = NULL,
};
static struct miscdevice lsf_factory_device = {
    .minor = MISC_DYNAMIC_MINOR,
    .name = "lsf-stream-factory",
    .mode = 0600,
    .fops = &lsf_factory_operations,
};

/* Future builtin entry; deliberately no initcall/Kconfig/Makefile today.
 * Even manually invoking this function cannot register an incomplete backend. */
int lsf_factory_register(void)
{
    if (!lsf_factory_selected_consumer() && !lsf_factory_constructor_qualification())
        return -EOPNOTSUPP;
    return misc_register(&lsf_factory_device);
}

